import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;
  const { textContent } = config;

  // Card dimensions based on aspect ratio 512/320 ≈ 1.6
  const width = 2.5;
  const height = width * (320 / 512);

  const group = new Group();

  // --- Backdrop plane with image texture ---
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10',
    transparent: true,
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.z = -0.01; // slight back offset
  group.add(mesh);

  // Load texture (async, sets material.map when ready)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text content ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textChild = null;
  for (const item of textItems) {
    if (item.text === 'Pricing 3') {
      // Use paper color for high contrast on dark surface
      const color = config.colors?.paper || '#e8ecf2';
      textChild = ctx.fontAtlas.createText(item.text, {
        fontSize: 39,
        color,
        align: 'center',
      });
      textChild.position.z = 0.01; // slightly above plane
      group.add(textChild);
      break;
    }
  }

  // --- Handlers (none needed) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
    // Dispose text children recursively
    group.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.dispose();
        if (child.geometry) child.geometry.dispose();
      }
    });
    // Remove text child references (will be garbage collected)
    if (textChild && textChild.parent) {
      textChild.parent.remove(textChild);
    }
  };

  return group;
}
